func splitSurfaceTools(value string) []string {
	entries := strings.Split(value, ",")
	out := make([]string, 0, len(entries))
	for _, entry := range entries {
		if entry = strings.TrimSpace(entry); entry != "" {
			out = append(out, entry)
		}
	}
	return out
}

func surfaceFor(args []string) (cliSurface, string) {
	readOnlyFlag, toolsFlag := false, false
	var flagTools string
	for i := 0; i < len(args); i++ {
		if args[i] == "--" {
			break
		}
		switch args[i] {
		case "--read-only":
			readOnlyFlag = true
		case "--tools":
			if i+1 >= len(args) || strings.HasPrefix(args[i+1], "-") {
				return cliSurface{}, "--tools needs a comma-separated list of resources, tool names, or resource.method."
			}
			if !toolsFlag {
				toolsFlag = true
				flagTools = args[i+1]
			}
			i++
		}
	}
	surface := cliSurface{
		readOnly:       readOnlyFlag || os.Getenv(mcpReadOnlyEnv) == "1" || os.Getenv(mcpReadOnlyEnv) == "true",
		readOnlySwitch: mcpReadOnlyEnv,
		includeSwitch:  mcpToolsEnv,
	}
	if readOnlyFlag {
		surface.readOnlySwitch = "--read-only"
	}
	includeValue := os.Getenv(mcpToolsEnv)
	if toolsFlag {
		includeValue = flagTools
		surface.includeSwitch = "--tools"
	}
	surface.include = splitSurfaceTools(includeValue)
	surface.includeSet = len(surface.include) > 0
	if toolsFlag && !surface.includeSet {
		return cliSurface{}, "--tools needs a comma-separated list of resources, tool names, or resource.method."
	}
	if surface.includeSet {
		unmatched := []string{}
		for _, wanted := range surface.include {
			found := false
			for _, op := range ops {
				if cliOpIncluded(op, wanted) {
					found = true
					break
				}
			}
			if !found {
				unmatched = append(unmatched, wanted)
			}
		}
		if len(unmatched) > 0 {
			resources := []string{}
			seen := map[string]bool{}
			for _, op := range ops {
				if op.APIResource != "" && !seen[op.APIResource] {
					resources = append(resources, op.APIResource)
					seen[op.APIResource] = true
				}
			}
			list := strings.Join(resources, ", ")
			if len(resources) > 30 {
				list = strings.Join(resources[:30], ", ") + ", …"
			}
			return cliSurface{}, surface.includeSwitch + " names nothing in this API: " + strings.Join(unmatched, ", ") + ". Resources: " + list + "."
		}
	}
	return surface, ""
}

func cliOpIncluded(op opDef, wanted string) bool {
	wanted = strings.ToLower(strings.TrimSpace(wanted))
	return strings.ToLower(op.Tool) == wanted ||
		strings.ToLower(op.APIResource) == wanted ||
		strings.ToLower(op.APIResource+"."+op.APIMethod) == wanted
}

func hiddenOperation(op opDef, surface cliSurface) (string, []string) {
	if surface.includeSet && !anySurfaceNameMatches(op, surface.include) {
		return op.Tool + " is not enabled on this server: " + surface.includeSwitch + " limits it to " + strings.Join(surface.include, ", ") + ".",
			[]string{"The operation needs a server whose " + surface.includeSwitch + " includes " + op.APIResource + "; tell the user if it is required."}
	}
	if surface.readOnly && !op.ReadOnly {
		return op.Tool + " is a write, and this server is read-only (" + surface.readOnlySwitch + "), so it cannot be called here.",
			[]string{"Writes need a server started without " + surface.readOnlySwitch + "; tell the user if this operation is required."}
	}
	return "", nil
}

func identitySurfaceError(op *opDef, args []string) (string, string, []string) {
	surface, problem := surfaceFor(args)
	if problem != "" {
		return "INVALID_USAGE", problem, nil
	}
	if message, next := hiddenOperation(*op, surface); message != "" {
		return "NOT_AVAILABLE", message, next
	}
	return "", "", nil
}

func anySurfaceNameMatches(op opDef, names []string) bool {
	for _, name := range names {
		if cliOpIncluded(op, name) {
			return true
		}
	}
	return false
}

func dryRunAuthArgs(args []string, dryRun bool) []string {
	if !dryRun || hasFlag(args, "--dry-run") {
		return args
	}
	withFlag := append([]string(nil), args...)
	return append(withFlag, "--dry-run")
}

// hasAgentMode reports whether args explicitly request agent or JSON output.
func hasAgentMode(args []string) bool {
	for i, a := range args {
		if a == "--mode=agent" || a == "--format=json" || a == "--json" || a == "--non-interactive" || (a == "--mode" && i+1 < len(args) && args[i+1] == "agent") || (a == "--format" && i+1 < len(args) && args[i+1] == "json") {
			return true
		}
	}
	return false
}

// hasHumanMode reports whether args explicitly request human output.
func hasHumanMode(args []string) bool {
	for i, a := range args {
		if a == "--mode=human" || (a == "--mode" && i+1 < len(args) && args[i+1] == "human") || a == "--format=human" || (a == "--format" && i+1 < len(args) && args[i+1] == "human") {
			return true
		}
	}
	return false
}

func isHelpOrVersionInvocation(args []string) bool {
	if len(args) == 0 {
		return false
	}
	switch args[0] {
	case "-h", "--help", "help", "-v", "--version", "version":
		return true
	}
	return hasFlag(args, "-h") || hasFlag(args, "--help")
}

// main runs the CLI with the process arguments and exits with its status.
func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

// run implements root, resource, and per-operation routing: -h/--help
// and -v/--version at the root, --help at every resource and operation
// level, per https://clig.dev — primary output on stdout, diagnostics
// on stderr, 0 on success, 1 on an SDK/API error, 2 on a usage error.
func run(args []string, stdout, stderr io.Writer) int {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()
	ctx = withNamedCredentialSourceCache(ctx)
	if hasAgentMode(args) {
		_ = os.Setenv(authPrefix+"_AGENT", "1")
		_ = os.Unsetenv(authPrefix + "_HUMAN")
	} else if hasHumanMode(args) {
		_ = os.Unsetenv(authPrefix + "_AGENT")
		_ = os.Setenv(authPrefix+"_HUMAN", "1")
	}
	for i, a := range args {
		if a == "--color=always" || (a == "--color" && i+1 < len(args) && args[i+1] == "always") {
			_ = os.Setenv(authPrefix+"_COLOR", "always")
		}
	}
	// Capture an explicit --non-interactive before stripGlobalPrefix removes
	// it: browser approval runs headless under an agent, but the explicit
	// non-interactive switch must keep login noninteractive and fail with
	// TTY_REQUIRED instead of starting a flow.
	if hasFlag(args, "--non-interactive") {
		_ = os.Setenv(authPrefix+"_EXPLICIT_NONINTERACTIVE", "1")
	}
	selectedProfile, filteredArgs, profileErr := resolveProfile(args)
	if profileErr != nil {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", profileErr.Error(), nil, nil, 2)
	}
	previousProfile, previousLegacyProblem := activeProfile, activeLegacyProblem
	activeProfile = selectedProfile
	activeLegacyProblem = nil
	defer func() {
		activeProfile, activeLegacyProblem = previousProfile, previousLegacyProblem
	}()
	args = filteredArgs
	originalArgs := args
	dryRun := dryRunRequested(originalArgs)
	args = stripGlobalPrefix(args)
	if len(args) == 0 {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", "a command is required", nil, []string{fmt.Sprintf("run '%s --help' for usage", bin)}, 2)
	}
	if activeProfile.Name != "default" {
		if _, err := os.Stat(activeProfile.Directory); os.IsNotExist(err) && args[0] != "login" && args[0] != "init" && args[0] != "config" {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", fmt.Sprintf("profile %q does not exist; run '%s login --profile %s' or configure it first", activeProfile.Name, bin, activeProfile.Name), nil, nil, 2)
		}
	}
	if !dryRun && args[0] != "init" && !isHelpOrVersionInvocation(args) {
		activeLegacyProblem = migrateLegacyDefault(args)
	}
	switch args[0] {
	case "-h", "--help":
		fmt.Fprint(stdout, rootHelp)
		return 0
	case "help":
		if code, handled := runOperationalCommand(ctx, args, originalArgs, stdout, stderr); handled {
			return code
		}
		fmt.Fprint(stdout, rootHelp)
		return 0
	case "-v", "--version", "version":
		fmt.Fprintf(stdout, "%s %s (%s %s, generated by Typeship)\n", bin, version, "Typeship", "1.0.0")
		return 0
	}
	if args[0] == "api" {
		surface, problem := surfaceFor(originalArgs)
		if problem != "" {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", problem, nil, nil, 2)
		}
		if surface.readOnly {
			return writeFailure(args, stdout, stderr, "NOT_AVAILABLE", "raw API calls are not available in read-only mode ("+surface.readOnlySwitch+").", nil, nil, 2)
		}
		if surface.includeSet {
			return writeFailure(args, stdout, stderr, "NOT_AVAILABLE", "raw API calls are not enabled by "+surface.includeSwitch+" because they do not select a generated operation.", nil, nil, 2)
		}
		return runRawAPICommand(ctx, append(append([]string{"api"}, originalArgs[:len(originalArgs)-len(args)]...), args[1:]...), stdout, stderr)
	}
	if dryRun {
		if len(args) < 2 || findOp(args[0], args[1]) == nil {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", "--dry-run applies only to API commands", nil, nil, 2)
		}
	}
	if code, handled := runOperationalCommand(ctx, args, originalArgs, stdout, stderr); handled {
		return code
	}
	if args[0] == "login" || args[0] == "logout" || args[0] == "whoami" || args[0] == "auth" || args[0] == "config" {
		if whoamiEnabled && (args[0] == "whoami" || (args[0] == "auth" && len(args) > 2 && args[1] == "check" && hasFlag(args[2:], "--live"))) {
			op := findOp(whoamiResource, whoamiCommand)
			if op != nil {
				code, message, next := identitySurfaceError(op, originalArgs)
				if code != "" {
					return writeFailure(args, stdout, stderr, code, message, nil, next, 2)
				}
			}
		}
		return runAuthCommand(ctx, args, originalArgs, stdout, stderr)
	}
	resourceHelpText, isResource := resourceHelp[args[0]]
	if !isResource {
		msg := fmt.Sprintf("unknown command %q", args[0])
		if s := suggestion(args[0], resourceOrder); s != "" {
			msg += fmt.Sprintf("; did you mean %q?", s)
		}
		return writeFailure(args, stdout, stderr, "UNKNOWN_COMMAND", msg, nil, []string{fmt.Sprintf("run '%s --help' for available commands", bin)}, 2)
	}
	if len(args) == 1 || args[1] == "-h" || args[1] == "--help" {
		fmt.Fprint(stdout, resourceHelpText)
		return 0
	}
	surface, problem := surfaceFor(originalArgs)
	if problem != "" {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", problem, nil, nil, 2)
	}
	op := findOp(args[0], args[1])
	if op == nil {
		msg := fmt.Sprintf("unknown command %q", strings.Join(args[:2], " "))
		if s := suggestion(args[1], resourceCommands(args[0])); s != "" {
			msg += fmt.Sprintf("; did you mean %q?", s)
		}
		return writeFailure(args, stdout, stderr, "UNKNOWN_COMMAND", msg, nil, []string{fmt.Sprintf("run '%s %s --help' for its commands", bin, args[0])}, 2)
	}
	positionals, values, data, help, err := parseOpArgs(*op, args[2:])
	if help {
		fmt.Fprint(stdout, op.Help)
		return 0
	}
	if message, next := hiddenOperation(*op, surface); message != "" {
		return writeFailure(args, stdout, stderr, "NOT_AVAILABLE", message, nil, next, 2)
	}
	if err != nil {
		code := "INVALID_USAGE"
		message := err.Error()
		if strings.Contains(err.Error(), "unknown flag") {
			code = "UNKNOWN_FLAG"
			if strings.HasPrefix(message, "unknown flag --") {
				name := strings.TrimPrefix(message, "unknown flag --")
				if close := suggestion(name, append(operationFlagNames(*op), "mode")); close != "" {
					message += fmt.Sprintf("; did you mean --%s?", close)
				}
			}
		}
		return writeFailure(args, stdout, stderr, code, message, nil, []string{fmt.Sprintf("Run '%s %s %s --help' for the flags this command takes.", bin, args[0], args[1])}, 2)
	}
	if op.Safety == "destructive" && !dryRun && !hasFlag(args, "--yes") && !hasFlag(args, "--force") && !hasFlag(args, "-y") {
		return writeFailure(args, stdout, stderr, "CONFIRMATION_REQUIRED", "destructive operation requires --yes confirmation", nil, []string{fmt.Sprintf("rerun with '%s --yes'", strings.Join(args[:2], " "))}, 2)
	}
	if len(positionals) != len(pathParams(*op)) {
		return writeFailure(args, stdout, stderr, "MISSING_ARGUMENT", fmt.Sprintf("expected %d positional argument(s), got %d", len(pathParams(*op)), len(positionals)), nil, []string{fmt.Sprintf("Run '%s %s %s --help' for the flags this command takes.", bin, args[0], args[1])}, 2)
	}
	if op.BodyKind != "binary" && op.BodyKind != "text" && len(data) > 0 {
		var valid json.RawMessage
		if err := json.Unmarshal(data, &valid); err != nil {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", "--data: invalid JSON: "+err.Error(), nil, []string{"Correct the input named in the message; no request was sent."}, 2)
		}
	}
	var dataFields map[string]bool
	if op.BodyStyle == "fields" && len(data) > 0 {
		var parsed map[string]json.RawMessage
		if err := json.Unmarshal(data, &parsed); err != nil {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", "--data: invalid JSON: "+err.Error(), nil, []string{"Correct the input named in the message; no request was sent."}, 2)
		}
		dataFields = make(map[string]bool)
		for name := range parsed {
			dataFields[name] = true
		}
	}
	missing := []string{}
	for _, p := range op.Params {
		if p.Kind == "path" || !p.Required {
			continue
		}
		if _, ok := values[p.Flag]; ok {
			continue
		}
		if dataFields != nil && dataFields[p.Name] {
			continue
		}
		missing = append(missing, "--"+p.Flag)
	}
	if len(missing) > 0 {
		return writeFailure(args, stdout, stderr, "MISSING_ARGUMENT", "Missing required: "+strings.Join(missing, ", "), nil, []string{fmt.Sprintf("Run '%s %s %s --help' for the flags this command takes.", bin, args[0], args[1])}, 2)
	}
	if op.BodyStyle == "data" && op.BodyRequired && len(data) == 0 {
		if op.BodyKind == "binary" {
			return writeFailure(args, stdout, stderr, "MISSING_ARGUMENT", "Missing required: --file <path> (this operation's request body is required)", nil, []string{fmt.Sprintf("Run '%s %s %s --help' for the flags this command takes.", bin, args[0], args[1])}, 2)
		}
		return writeFailure(args, stdout, stderr, "MISSING_ARGUMENT", "Missing required: --data '<json>' (this operation's request body is required)", nil, []string{fmt.Sprintf("Run '%s %s %s --help' for the flags this command takes.", bin, args[0], args[1])}, 2)
	}
	data, err = validateOperationInput(*op, positionals, values, data)
	if err != nil {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", err.Error(), nil, []string{"Correct the input named in the message; no request was sent."}, 2)
	}
	if err := validateAuthFlags(args); err != nil {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", err.Error(), nil, nil, 2)
	}
	if values["__out"].scalar != "" && op.BundleField == "" {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", "--out applies only to file-shaped responses", nil, nil, 2)
	}
	opts, optErr := authOptions(ctx, dryRunAuthArgs(args, dryRun), op, originalArgs)
	if optErr != nil {
		return writeAuthOptionsFailure(args, stdout, stderr, optErr)
	}
	var capture *dryRunTransport
	if dryRun {
		capture = &dryRunTransport{}
		opts = append(opts, dryRunClientOption(capture))
	}
	client, err := sdk.New(opts...)
	if err != nil {
		return writeFailure(args, stdout, stderr, failureCode(err), "unable to initialize the client", errorDetail(err, args), nil, 1)
	}
	result, err := invoke(client, ctx, *op, positionals, values, data)
	if dryRun && capture.request == nil {
		if op.Paginated {
			if iterator, ok := result.(cliIterator); ok {
				_, _ = iterator.FirstPage()
			}
		}
		if op.SSE {
			startDryRunStream(result)
		}
	}
	if dryRun && capture.request != nil {
		return writeDryRunPreview(args, capture, stdout, stderr)
	}
	if err != nil {
		if ctx.Err() != nil {
			return 130
		}
		if writeNotModified(err, stdout) {
			return 0
		}
		return writeRequestFailure(args, stdout, stderr, err)
	}
	if op.SSE {
		if streamErr := renderCLIStream(result, values["__fields"].scalar, stdout); streamErr != nil {
			if isRequestFailure(streamErr) {
				return writeRequestFailure(args, stdout, stderr, streamErr)
			}
			return writeFailure(args, stdout, stderr, "CALL_FAILED", "stream failed", streamErr.Error(), nil, 1)
		}
		return 0
	}
	if op.Paginated {
		iterator, ok := result.(cliIterator)
		if !ok {
			return writeFailure(args, stdout, stderr, "CALL_FAILED", "pagination response has an unexpected type", nil, nil, 1)
		}
		if values["__all"].scalar == "true" {
			for iterator.Next() {
				projected, projectErr := projectJSON(iterator.ValueAny(), values["__fields"].scalar)
				if projectErr != nil {
					return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not project response", projectErr.Error(), nil, 1)
				}
				line, marshalErr := json.Marshal(projected)
				if marshalErr != nil {
					return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not encode response", marshalErr.Error(), nil, 1)
				}
				if _, writeErr := fmt.Fprintln(stdout, string(line)); writeErr != nil {
					return writeFailure(args, stdout, stderr, "CALL_FAILED", "stream failed", writeErr.Error(), nil, 1)
				}
			}
			if iterator.Err() != nil {
				if writeNotModified(iterator.Err(), stdout) {
					return 0
				}
				return writeRequestFailure(args, stdout, stderr, iterator.Err())
			}
			return 0
		}
		envelope, pageErr := iterator.FirstPage()
		if writeNotModified(pageErr, stdout) {
			return 0
		}
		if pageErr != nil {
			return writeRequestFailure(args, stdout, stderr, pageErr)
		}
		result = envelope
	}
	if op.BundleField != "" || values["__fields"].scalar != "" {
		rendered, renderErr := renderValue(result, values["__fields"].scalar, values["__out"].scalar, op.BundleField, op.CollectionField)
		if renderErr != nil {
			return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not render response", renderErr.Error(), nil, 1)
		}
		result = rendered
	}
	out, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not encode response", err.Error(), nil, 1)
	}
	fmt.Fprintln(stdout, string(out))
	return 0
}

// writeNotModified reports a 304 as a result, not a failure: the
// conditional request matched, so the output says so, with the ETag to
// send next time.
func writeNotModified(err error, stdout io.Writer) bool {
	var notModified *sdk.NotModifiedError
	if !errors.As(err, &notModified) {
		return false
	}
	report := struct {
		Ok          bool   `json:"ok"`
		NotModified bool   `json:"not_modified"`
		ETag        string `json:"etag,omitempty"`
	}{Ok: true, NotModified: true, ETag: notModified.ETag()}
	b, _ := json.MarshalIndent(report, "", "  ")
	fmt.Fprintln(stdout, string(b))
	return true
}
